// The HTTP node's array-splitting for a top-level PostgREST array has varied
// across n8n versions, so flatten defensively rather than assuming one row per item.
const rows = [];
for (const item of $input.all()) {
  const value = item.json;
  if (Array.isArray(value)) { rows.push(...value); }
  else if (value) { rows.push(value); }
}
return rows.filter(row => row && row.id && row.post_id).map(row => ({ json: row }));

// The HTTP node replaced $json with the credential response, dropping the post
// row's own fields. Pull the row back at the same item index and merge.
const post = $('Normalize Posts To Check').item.json;
const cred = $input.item.json || {};
if (!cred.success) {
  throw new Error('Credential lookup failed for branch ' + post.branch_id + ': ' + (cred.error || 'unknown error'));
}
const pageId = cred.platform_metadata?.page_id;
if (!pageId) throw new Error('page_id missing from platform_metadata for branch ' + post.branch_id);
// Page post insights require a PAGE token; use one directly if stored, else the
// user token, which 'Resolve Page Token' exchanges downstream.
const token = (cred.platform_metadata?.page_access_token || cred.access_token || '').trim();
if (!token) throw new Error('No Facebook token stored for branch ' + post.branch_id);
return { json: { ...post, page_id: pageId, stored_token: token } };

const src = $('Merge Credential With Post').item.json;
const res = $input.item.json || {};
let parsed = res.body;
if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch (e) { parsed = null; } }
const exchanged = parsed && typeof parsed.access_token === 'string' ? parsed.access_token.trim() : '';
return { json: { ...src, access_token: exchanged || src.stored_token } };

// Facebook returns one entry per metric in data[], each with values[0].value.
// A metric can be absent entirely (varies by post type and API version), so look
// each up by name and leave it null rather than failing the row or inventing a 0.
const response = $input.item.json || {};
const source = $('Choose Page Token').item.json || {};
const metricsData = Array.isArray(response.data) ? response.data : [];

function metricValue(name) {
  const entry = metricsData.find(m => m && m.name === name);
  const raw = entry && Array.isArray(entry.values) && entry.values.length ? entry.values[0].value : undefined;
  if (raw === undefined || raw === null) return null;
  return raw;
}

const impressions = metricValue('post_impressions');
const reachUnique = metricValue('post_impressions_unique');
const engaged = metricValue('post_engaged_users');
const clicks = metricValue('post_clicks');
const reactionsByType = metricValue('post_reactions_by_type_total');

// post_reactions_by_type_total is an object like { like: 4, love: 1 } -- sum it
// for a single 'likes' figure, but keep the breakdown in raw.
let reactionTotal = null;
if (reactionsByType && typeof reactionsByType === 'object') {
  reactionTotal = Object.values(reactionsByType).reduce((sum, v) => sum + (Number(v) || 0), 0);
}

return { json: {
  platform: 'facebook',
  scheduled_post_id: source.id,
  ig_media_id: source.post_id,
  branch_slug: source.branch_slug,
  impressions: impressions,
  reach: reachUnique,
  likes: reactionTotal,
  comments: null,
  saves: null,
  shares: null,
  raw: {
    post_impressions: impressions,
    post_impressions_unique: reachUnique,
    post_engaged_users: engaged,
    post_clicks: clicks,
    post_reactions_by_type_total: reactionsByType
  },
  fetched_at: new Date().toISOString()
} };
